insert into public.experience_questions (topic, experience_band, question, answer, example, is_free) values
('C# / .NET', '0-2 years', 'What is dependency injection, and when would you use it in a .NET application?', 'Dependency injection provides a class with the services it needs instead of having it construct those services directly. It improves testability and makes dependencies visible. In .NET, register services with the container and choose lifetimes deliberately: scoped for request work, singleton only for safe shared state, and transient for lightweight stateless services.', 'Inject an IOrderRepository into an OrderService and replace it with a fake in a unit test.', true),
('C# / .NET', '0-2 years', 'How do async and await work in an ASP.NET Core endpoint?', 'await lets an asynchronous method yield while an I/O operation is incomplete, so the request thread can do other work. It does not make CPU-heavy work faster. Return Task or Task<T>, await database and HTTP calls, and avoid .Result and .Wait because they block threads.', 'Await orderRepository.GetByIdAsync(id, cancellationToken), then return NotFound or Ok based on the result.', false),
('C# / .NET', '3-5 years', 'How would you design a reliable ASP.NET Core API endpoint for creating an order?', 'Validate the request at the boundary, enforce authorization and business invariants in the application layer, use an explicit transaction for the database write, and return a stable response contract. Add idempotency when clients may retry and propagate cancellation to dependencies.', 'A unique customer/idempotency-key pair prevents a timeout retry from creating a second order.', true),
('C# / .NET', '3-5 years', 'How do you prevent a slow downstream dependency from exhausting API capacity?', 'Set bounded timeouts, propagate cancellation, limit concurrency, and use retries only for transient failures with backoff and jitter. Avoid retrying non-idempotent operations unless they have an idempotency mechanism. Observe latency and saturation so the policy can be tuned from evidence.', 'Use a typed HttpClient with a timeout and a bounded resilience pipeline; do not retry validation errors.', false),
('C# / .NET', '6-10 years', 'How would you evolve a large .NET service without breaking existing API clients?', 'Treat the API as a compatibility contract: add optional fields before removing anything, preserve current semantics, validate changes with consumer contract tests, and version only when a breaking change is unavoidable. Roll out with telemetry and a rollback path.', 'Add a response field first, measure adoption, then deprecate an old field through a communicated version window.', true),
('C# / .NET', '6-10 years', 'How do you diagnose thread-pool starvation in a production .NET service?', 'Correlate request latency with thread-pool queue length, active threads, CPU, and dependency latency. Look for sync-over-async, blocking locks, long synchronous I/O, and unbounded work. Fix the blocking source before increasing thread limits, then load-test the change.', 'A controller calling Task.Result on an HTTP request can block worker threads while waiting on I/O and amplify latency under load.', false),
('C# / .NET', '10+ years', 'How do you decide whether a .NET domain should be a modular monolith or a separate service?', 'Start with ownership and change boundaries, not deployment fashion. A modular monolith can preserve strong transactions and simpler operations; split a service when independent scaling, ownership, isolation, or release cadence justifies the operational and consistency cost. Define data ownership and migration triggers explicitly.', 'Keep checkout modules together while the team and transaction model are coupled; extract fulfillment when its ownership and scaling profile become distinct.', true),
('C# / .NET', '10+ years', 'How would you lead a migration from a legacy .NET application to a supported platform?', 'Inventory runtime and dependency risks, define target outcomes, and build a tested migration path with a representative vertical slice. Prefer incremental compatibility and automated verification over a risky rewrite. Track security support, operational readiness, and measurable rollback criteria.', 'Upgrade a low-risk service first, validate observability and deployment, then migrate shared libraries and higher-criticality services in planned waves.', false),
('Angular', '0-2 years', 'What is the difference between an Angular component and a service?', 'A component owns a view and handles user interaction for that view. A service holds reusable logic or data access and is provided through dependency injection. Keeping HTTP and shared business logic out of components makes the UI easier to test and reuse.', 'A ProductListComponent renders products while a ProductService loads them from an API.', true),
('Angular', '0-2 years', 'When would you use an Observable in an Angular application?', 'An Observable represents values that may arrive over time and can be transformed or canceled by unsubscribing. Angular HTTP calls return Observables. Use the async pipe for template subscriptions where possible so Angular handles subscription cleanup.', 'Use valueChanges with debounceTime and switchMap for a search input that requests matching products.', false),
('Angular', '3-5 years', 'How would you prevent stale search results from replacing newer results?', 'Treat each query as a new stream, debounce input, then use switchMap so the previous inner request is unsubscribed when a newer query arrives. Model loading, error, and success states explicitly, and ensure the UI reflects the active query.', 'A user types “ca” then “camera”; a delayed “ca” response must not overwrite the “camera” results.', true),
('Angular', '3-5 years', 'How do you decide between local component state and a shared state service?', 'Keep state local when one component or a small subtree owns it. Use a shared service for a small number of cross-component workflows; use a state library when state transitions, effects, debugging needs, or team coordination justify its ceremony. Avoid duplicating derived state.', 'A dialog open flag belongs in its parent; a multi-step checkout cart may need a shared state owner.', false),
('Angular', '6-10 years', 'How would you improve a slow Angular application used on lower-powered devices?', 'Measure startup and interaction costs first. Reduce initial JavaScript through lazy routes and bundle analysis, avoid unnecessary change detection and expensive template expressions, virtualize large lists, and defer non-critical work. Verify improvements on realistic devices and network profiles.', 'Lazy-load the admin route and use stable tracking for rows in a large results table.', true),
('Angular', '6-10 years', 'How do you structure an Angular frontend used by multiple teams?', 'Define feature ownership, routing boundaries, shared design-system contracts, and rules for dependency direction. Keep shared libraries small and stable, automate lint and contract checks, and avoid a single global state layer that couples unrelated features.', 'Teams own separate feature libraries while common UI primitives are versioned and reviewed through a design-system contract.', false),
('Angular', '10+ years', 'How would you plan an Angular modernization across a large product?', 'Baseline user and engineering outcomes, map framework and library dependencies, and migrate incrementally through supported compatibility paths. Establish reusable patterns, automated visual and behavior tests, and ownership for shared libraries. Avoid bundling unrelated redesigns into the framework migration.', 'Migrate a representative route first, validate routing, forms, accessibility, and release monitoring, then sequence the remaining features by risk.', true),
('Angular', '10+ years', 'How do you set frontend architecture standards without blocking product teams?', 'Standardize only cross-cutting needs such as accessibility, security, observability, and supported dependencies. Provide paved-road templates and measurable checks, delegate local decisions to feature teams, and revisit standards using incident and delivery evidence.', 'Offer a tested route and API-client template rather than requiring every feature to use one global component structure.', false),
('Azure', '0-2 years', 'What is a managed identity, and why is it useful in Azure?', 'A managed identity gives an Azure resource an identity in Microsoft Entra ID so it can request tokens for supported services. It avoids storing a long-lived password or client secret in application configuration. Grant only the roles and scope the application needs.', 'An App Service identity can receive a narrowly scoped Key Vault secret-read role.', true),
('Azure', '0-2 years', 'How would you store an application secret used by an Azure-hosted service?', 'Store secrets in a managed secret store such as Azure Key Vault, access them with managed identity, restrict permissions, and rotate them. Do not commit credentials or expose them in browser code, logs, or deployment artifacts.', 'An API reads a payment-provider secret from Key Vault using its managed identity at runtime.', false),
('Azure', '3-5 years', 'How would you make an Azure-hosted API resilient to a dependency outage?', 'Use bounded dependency timeouts, retry only transient and safe operations, add circuit breaking or concurrency limits where appropriate, and degrade non-critical functionality deliberately. Instrument dependency latency and failures and test the behavior under fault conditions.', 'If recommendations are unavailable, checkout can continue while the API returns a documented fallback rather than waiting indefinitely.', true),
('Azure', '3-5 years', 'When would you choose a queue between two Azure services?', 'Use a queue to decouple producers and consumers, absorb bursts, and retry work independently. Design consumers to be idempotent, set a visibility or lock strategy, handle poison messages, and monitor queue age as well as depth.', 'Order placement publishes an event; fulfillment processes it later and records the event ID to avoid duplicate work.', false),
('Azure', '6-10 years', 'How do you investigate an Azure service that is healthy by probe but failing for users?', 'Trace a real request across edge, application, identity, network, and dependencies. Compare user-facing availability with probe health, inspect correlated traces and dependency metrics, and validate DNS, certificates, quotas, and regional routing. Use synthetic checks that exercise critical user journeys.', 'A readiness probe can pass while a required downstream database is unreachable, so combine shallow process health with dependency-aware telemetry.', true),
('Azure', '6-10 years', 'How would you structure Azure environments and deployment promotion?', 'Separate environment configuration and access, use reproducible infrastructure as code, promote immutable build artifacts, and apply least privilege to deployment identities. Add staged rollout, automated health checks, and a tested rollback or roll-forward plan.', 'Build once, deploy the same container digest to staging and production, changing only approved environment configuration.', false),
('Azure', '10+ years', 'How do you choose a multi-region strategy for a critical Azure workload?', 'Start with recovery objectives, data consistency requirements, and failure domains. Active-active may improve availability but increases conflict, routing, and operational complexity; active-passive can be simpler but may increase recovery time. Test regional failover and failback with owners and explicit data-loss bounds.', 'A globally readable catalog may use active-active replicas while order writes remain home-region routed with a documented recovery point objective.', true),
('Azure', '10+ years', 'How would you govern Azure resources across many teams while preserving delivery speed?', 'Establish a secure landing-zone baseline, identity and network boundaries, policy guardrails, centralized cost and security visibility, and self-service templates. Keep exceptions time-bound and owned, and automate evidence collection instead of relying on manual review for every change.', 'Teams deploy through approved templates while policy blocks public storage by default and allows a documented exception with an expiry.', false),
('SQL', '0-2 years', 'What is an index, and what trade-off does it introduce?', 'An index is an additional data structure that helps the database find rows without scanning the full table. It speeds some reads but consumes storage and adds work to inserts, updates, and deletes. Choose indexes based on actual filters, joins, and ordering.', 'An index on customer_id can speed order history lookups, but every new order must also update that index.', true),
('SQL', '0-2 years', 'What does a database transaction provide?', 'A transaction groups changes so they commit together or roll back together. ACID describes atomicity, consistency, isolation, and durability. Use a transaction when a business operation must not leave only part of its database changes applied.', 'Creating an order and reserving its inventory record may need one transaction when both changes share a database.', false),
('SQL', '3-5 years', 'How would you investigate a slow SQL query?', 'Capture the exact query and representative parameters, inspect the execution plan and actual row counts, then check scans, join choices, cardinality estimates, and waits. Add or adjust indexes only after understanding the access path; also check returned row volume and application round trips.', 'A query filtering by tenant and created date may need a composite index aligned to those predicates and the sort order.', true),
('SQL', '3-5 years', 'How do isolation levels affect concurrent transactions?', 'Isolation levels trade consistency guarantees against blocking and concurrency. The exact anomalies and implementation depend on the database engine. Identify the invariant the business operation needs, use constraints for durable rules, and test competing transactions rather than selecting the strongest level by default.', 'A unique constraint prevents duplicate usernames even when two requests race; an application-side pre-check alone does not.', false),
('SQL', '6-10 years', 'How would you safely introduce a new required column to a large production table?', 'Use an expand-and-contract migration: add the nullable column, deploy code that can read old and new shapes, backfill in bounded batches, verify completeness, then enforce not-null and remove obsolete paths in a later release. Monitor locks, replication lag, and application compatibility.', 'Deploy writers that populate the new column before running a throttled backfill, then add the constraint after validation.', true),
('SQL', '6-10 years', 'How do you decide between partitioning and adding another index?', 'An index is usually the simpler first tool for selective access. Partitioning can help with very large data, lifecycle operations, or pruning when queries align with the partition key, but it adds operational and query-planning constraints. Use workload and growth measurements to justify the extra complexity.', 'Time-based partitioning can make monthly retention cheaper, but it will not help queries that cannot filter on the partition key.', false),
('SQL', '10+ years', 'How would you scale a relational data model beyond one primary database?', 'First reduce unnecessary load with query, index, caching, and workload improvements. Then evaluate read replicas, partitioning, or sharding based on consistency, write throughput, tenant distribution, and operational readiness. Define ownership, cross-shard query behavior, rebalancing, and recovery before splitting data.', 'Shard by a stable tenant key only if tenant traffic is sufficiently distributed and cross-tenant transactions can be redesigned.', true),
('SQL', '10+ years', 'How do you lead a database reliability and performance program?', 'Establish service-level objectives for latency, availability, and recovery; connect query-level telemetry to product critical paths; and prioritize fixes by user impact and risk. Protect schema changes with compatibility practices, capacity planning, backup restore tests, and clear ownership.', 'Track the p95 latency and error budget of checkout queries, and regularly exercise point-in-time recovery rather than only checking that backups exist.', false),
('System Design', '0-2 years', 'How do you start answering a system-design interview question?', 'Clarify who uses the system, the core use cases, and important constraints before drawing components. Estimate scale only enough to guide choices, then describe a simple design and walk through one critical request end to end.', 'For a URL shortener, clarify redirect volume, link creation, expiry, and whether custom aliases are required.', true),
('System Design', '0-2 years', 'What is the difference between a cache and a database?', 'A database is the durable source of truth for application data. A cache stores derived or copied data to reduce latency or load and may evict entries. Decide how cache entries are populated, invalidated, and allowed to become stale.', 'A product page can cache catalog details briefly while the database remains authoritative for inventory.', false),
('System Design', '3-5 years', 'How would you design an API that can safely handle client retries?', 'Give the operation an idempotency key scoped to the caller, persist the request outcome atomically with the operation, and return the same result for a duplicate key. Set key expiry and conflict semantics, and distinguish retries from genuinely new requests.', 'A payment creation endpoint stores the idempotency key and payment result so a network retry does not charge twice.', true),
('System Design', '3-5 years', 'How do you choose between synchronous calls and asynchronous messaging?', 'Use synchronous calls when the caller needs an immediate result and coupling is acceptable. Use messaging for independent work, burst absorption, or eventual consistency, while adding idempotency, ordering decisions, retries, and dead-letter handling. Explain the user-visible trade-off.', 'Checkout can confirm order acceptance synchronously, then publish fulfillment work asynchronously.', false),
('System Design', '6-10 years', 'How would you find the bottleneck when traffic suddenly increases?', 'Follow a representative request and correlate throughput, latency, errors, saturation, and dependency metrics by service and endpoint. Separate queueing from service time, examine hot partitions and connection pools, and test a targeted hypothesis with load replay before scaling broadly.', 'Rising API latency with a growing database connection wait may point to pool or query saturation rather than insufficient web replicas.', true),
('System Design', '6-10 years', 'How do you choose a consistency model for a distributed feature?', 'Start from user-visible invariants and identify which operations require read-your-writes, ordering, or atomicity. Keep strong consistency for critical invariants where needed and accept bounded staleness elsewhere, with reconciliation and observability for asynchronous paths.', 'A profile display name may tolerate a short propagation delay, while a payment authorization decision must use an authoritative state.', false),
('System Design', '10+ years', 'How would you evolve a monolith into services without creating a distributed monolith?', 'Map domain ownership and change coupling, establish explicit data ownership, and extract one bounded capability with an independently valuable operational reason. Replace in-process assumptions with versioned contracts, asynchronous workflows where appropriate, and team ownership; measure the added latency and failure modes.', 'Extract image processing when its scaling and release needs differ, while keeping tightly coupled checkout invariants together until they can be separated safely.', true),
('System Design', '10+ years', 'How do you set reliability targets and decide what to build next?', 'Translate customer expectations into service-level indicators and objectives, then use error budgets and incident evidence to balance feature delivery with reliability work. Prioritize improvements by critical user journeys, blast radius, recovery time, and cost rather than chasing uniform availability everywhere.', 'A checkout SLO may warrant multi-region recovery investment while an internal reporting page can use a slower recovery target.', false),
('JavaScript / TypeScript', '0-2 years', 'What is the difference between let, const, and var?', 'let and const are block-scoped; var is function-scoped and has older hoisting behavior that can make code harder to reason about. Use const by default when the binding will not be reassigned, and let when reassignment is needed. const does not make an object deeply immutable.', 'Use const user = { name: "A" }; the binding cannot point to another object, but user.name can still be changed.', true),
('JavaScript / TypeScript', '0-2 years', 'What does TypeScript add to JavaScript?', 'TypeScript adds static type checking and language tooling that help catch mismatches during development, then compiles to JavaScript. Types are erased at runtime, so external data still needs runtime validation.', 'A type says an API response should contain an id, but validate the JSON before treating untrusted response data as that type.', false),
('JavaScript / TypeScript', '3-5 years', 'How do you handle errors in an async JavaScript workflow?', 'Use try/catch around awaited operations, preserve useful error context, and handle expected failures explicitly. For concurrent work, choose Promise.all when all results are required or allSettled when each result should be inspected independently. Do not silently convert failures into success-shaped defaults.', 'Load independent dashboard cards with allSettled so one optional widget failing does not hide every successful widget.', true),
('JavaScript / TypeScript', '3-5 years', 'How do you model API data safely in TypeScript?', 'Treat network data as unknown until runtime validation succeeds. Use discriminated unions for meaningful states, narrow types through guards, and keep optional or nullable fields explicit. Static assertions alone do not validate JSON received at runtime.', 'Parse an API payload with a schema or explicit guard before using its status field to choose a UI state.', false),
('JavaScript / TypeScript', '6-10 years', 'How would you diagnose excessive rerenders in a React application?', 'Profile the actual interaction, identify which state updates and component subtrees are involved, and check unstable props, broad context updates, and expensive derived work. Fix ownership or data flow first; memoize only measured hot paths and verify the improvement with profiling.', 'Move a frequently changing input state closer to its field instead of causing a large page context to update on every keystroke.', true),
('JavaScript / TypeScript', '6-10 years', 'How do you evolve a shared TypeScript library without disrupting consumers?', 'Define and test the public contract, use semantic versioning for breaking changes, and validate downstream usage with type tests or consumer fixtures. Prefer additive changes and explicit deprecation windows; avoid leaking internal implementation types into the API.', 'Export a stable public options type instead of exposing a type inferred from a private implementation detail.', false),
('JavaScript / TypeScript', '10+ years', 'How do you establish a sustainable frontend platform for multiple product teams?', 'Create a small set of stable primitives for accessibility, telemetry, build and dependency policy, and shared design language. Provide a paved road with clear ownership and migration support, while letting teams own feature decisions. Track adoption and friction instead of enforcing abstractions without evidence.', 'Version a design system with supported migration notes and usage telemetry rather than creating a single release train for every product.', true),
('JavaScript / TypeScript', '10+ years', 'How would you prioritize frontend performance across a large product?', 'Prioritize by user impact and measured experience: identify critical journeys, segment real-user metrics by device and network, and address the largest contributors to loading and interaction delay. Set budgets at meaningful boundaries and make regressions visible in CI and production.', 'Use route-level JavaScript and interaction metrics to prioritize the checkout journey instead of optimizing a low-traffic settings page first.', false)
insert into public.experience_questions (topic, experience_band, question, answer, example, is_free) values
('EF Core', '0-2 years', 'What problem does Entity Framework Core solve?', 'EF Core is an object-relational mapper that lets .NET code work with database data through entities and a DbContext. It translates supported LINQ queries into database commands, tracks changes, and saves them. Developers still need to understand the generated SQL and database behavior.', 'Load an Order with FirstOrDefaultAsync, change its Status, and call SaveChangesAsync to persist the update.', false),
('EF Core', '0-2 years', 'What is a DbContext and how should its lifetime be managed?', 'A DbContext represents a unit of work: it coordinates queries, change tracking, and saves. It is not thread-safe, so do not use it concurrently or keep it as a long-lived singleton. In a web app, a scoped context per request is a common default.', 'Register AddDbContext in ASP.NET Core and await one request''s database operations sequentially.', false),
('EF Core', '3-5 years', 'When should you use AsNoTracking for an EF Core query?', 'Use AsNoTracking for read-only results that do not need change tracking. It can reduce memory and tracking overhead for larger reads. Do not use it when the same context must track and persist modifications to the returned entities.', 'A product catalog endpoint can project products to response DTOs with AsNoTracking.', false),
('EF Core', '3-5 years', 'How do EF Core migrations help a team evolve a database?', 'Migrations record schema changes as reviewed, ordered code artifacts. Generate them from model changes, inspect the SQL and constraints, and apply them through a controlled deployment process. Production rollout must account for compatibility with the currently running application version.', 'Add a nullable column first, deploy code that can read both shapes, backfill, and make it required in a later migration.', false),
('EF Core', '6-10 years', 'How do you diagnose an EF Core query that is slow in production?', 'Capture the generated SQL and parameters safely, inspect the database execution plan, and correlate query duration with row counts, indexes, locks, and connection-pool behavior. Check for N+1 queries, excessive includes, client-side work, and unbounded result sets before changing the ORM configuration.', 'Use query logging with sensitive data disabled, then compare the plan for the endpoint''s common filters against its current indexes.', false),
('EF Core', '6-10 years', 'How do you prevent lost updates when multiple users edit the same record?', 'Use optimistic concurrency with a concurrency token such as a row version. EF Core includes the original token in the update predicate; if another writer changed the row, the update affects no rows and raises a concurrency exception that the application must handle deliberately.', 'Show the user a conflict message and let them reload or reconcile when the row version no longer matches.', false),
('EF Core', '10+ years', 'How would you decide between EF Core, raw SQL, and a micro-ORM?', 'Choose per workload and team capability rather than by blanket rule. EF Core offers productive domain persistence and composable queries; raw SQL or a micro-ORM can fit specialized, measured query paths. Keep transaction boundaries, parameterization, observability, and ownership consistent across approaches.', 'Keep ordinary aggregate writes in EF Core and isolate a measured reporting query behind a repository using parameterized SQL.', false),
('EF Core', '10+ years', 'How do you deploy database changes safely when application instances roll independently?', 'Use an expand-and-contract sequence: introduce backward-compatible schema, deploy code that works with old and new representations, migrate data in bounded batches, then remove obsolete schema after all consumers move. Make each phase observable and reversible where possible.', 'Add a new indexed column, dual-write temporarily, backfill in batches, switch reads, then remove the old column in a later release.', false),
insert into public.experience_questions (topic, experience_band, question, answer, example, is_free) values
('C# / .NET', '0-2 years', 'What is the difference between a value type and a reference type in C#?', 'A value-type variable holds its value directly, while a reference-type variable holds a reference to an object. Copying them therefore has different behavior, but actual memory placement depends on context and should not be reduced to the oversimplification that every value is always on the stack.', 'Two variables assigned the same class instance refer to that instance, while copying an int creates an independent value.', false),
('C# / .NET', '0-2 years', 'Why should a C# class implement IDisposable?', 'A type should implement IDisposable when it owns resources that require deterministic release, such as a file handle or a disposable child object. Call Dispose through using or await using where appropriate; garbage collection alone does not guarantee timely release of external resources.', 'Wrap a FileStream in a using declaration so the handle is closed when the scope exits.', false),
('C# / .NET', '3-5 years', 'When should you use a record instead of a class in C#?', 'A record is useful when value-oriented equality and concise data modeling match the type''s purpose. A class is often clearer for entities with identity and mutable lifecycle. Choose based on equality semantics and domain meaning, not only syntax preference.', 'A request DTO can be a record, while an order entity with a stable identity and lifecycle may be a class.', false),
('C# / .NET', '3-5 years', 'How do cancellation tokens improve asynchronous .NET code?', 'CancellationToken communicates that a caller no longer needs work to continue. Pass it through cancellable async operations, check it in long-running loops, and distinguish expected cancellation from faults. Cancellation is cooperative and does not forcibly stop arbitrary code.', 'Pass RequestAborted to database and HTTP calls so work can stop after a client disconnects.', false),
('C# / .NET', '6-10 years', 'How do you investigate high garbage-collection allocation in a .NET service?', 'Measure allocation rate and GC pauses with runtime counters or traces, identify hot allocation paths, and inspect object lifetimes before optimizing. Reduce avoidable temporary objects or oversized buffers only where measurements show a real impact, then validate throughput and latency under representative load.', 'A trace may reveal repeated JSON serialization of the same large response as a significant allocation source.', false),
('C# / .NET', '6-10 years', 'When would you use Channel<T> in a .NET service?', 'Channel<T> provides asynchronous producer-consumer coordination. A bounded channel can apply backpressure within a process, but it is not durable across restarts. Choose it for in-memory coordination only when loss and recovery semantics are acceptable.', 'Use a bounded channel to limit concurrent image-processing work, but persist jobs to a durable queue if restart recovery is required.', false),
('C# / .NET', '10+ years', 'How do you choose a consistency boundary for a .NET domain model?', 'Place invariants that must hold atomically inside a transaction boundary the domain can enforce. Avoid spanning unrelated workflows in one aggregate or database transaction; use explicit asynchronous coordination and compensations for broader processes.', 'Reserve inventory within its own consistency boundary and coordinate with payment through a durable workflow.', false),
('C# / .NET', '10+ years', 'How would you establish a sustainable .NET upgrade strategy across many services?', 'Inventory support lifecycles and dependency ownership, define supported runtime baselines, and automate repeatable upgrade validation. Migrate incrementally with representative services, measure security and operational outcomes, and provide teams a tested path rather than relying on last-minute large upgrades.', 'Create an automated compatibility pipeline and migrate a low-risk service before setting a fleet-wide retirement date.', false),
('Angular', '0-2 years', 'What is data binding in Angular?', 'Data binding connects component state with a template. Interpolation displays values, property binding sets element properties, event binding handles user actions, and two-way binding combines input and output flow where appropriate.', 'Bind a product name with interpolation and handle a button click with event binding.', false),
('Angular', '0-2 years', 'What is the purpose of an Angular directive?', 'A directive adds behavior to an element or changes how template content is rendered. Built-in structural and attribute directives cover common cases; custom directives are useful when behavior should be reusable and independent from one view.', 'Use an attribute directive to apply consistent focus behavior to form controls.', false),
('Angular', '3-5 years', 'How do Angular route guards help protect a route?', 'A route guard can decide whether navigation should proceed based on application state, such as authentication. It improves navigation behavior but is not a security boundary; the server must independently authorize every protected operation.', 'Redirect an unauthenticated user to sign-in while the API still checks the user''s permissions.', false),
('Angular', '3-5 years', 'How should an Angular application handle an HTTP error?', 'Handle errors at the narrowest layer that can respond meaningfully, preserve structured error details, and expose clear loading and retry states. Central interceptors can handle cross-cutting concerns but should not hide feature-specific failures or turn errors into false success.', 'An interceptor can attach a correlation ID while a feature displays a retry option for a failed read.', false),
('Angular', '6-10 years', 'How do you make a large Angular form maintainable?', 'Separate form state from presentation, group controls around domain concepts, define reusable validators, and keep conditional behavior explicit. Test validation and accessibility, and avoid constructing a highly coupled form whose controls depend on hidden ordering or side effects.', 'Build a typed FormGroup for address details and isolate postal-code validation in a reusable validator.', false),
('Angular', '6-10 years', 'How do you evaluate whether OnPush change detection is appropriate?', 'Use OnPush when component inputs and event-driven updates provide clear change boundaries. Keep state updates immutable or otherwise ensure Angular is notified; measure before and after, and check third-party or asynchronous update paths for stale views.', 'Use immutable input updates for a large read-only result list and verify all async updates trigger rendering.', false),
('Angular', '10+ years', 'How would you govern shared frontend dependencies across multiple Angular applications?', 'Define supported versions, ownership, security response expectations, and a tested upgrade cadence. Prefer compatible shared libraries with clear public APIs, track dependency drift, and give product teams automated migration support instead of forcing synchronized upgrades without need.', 'Publish a compatibility matrix and automated update pull requests for maintained Angular applications.', false),
('Angular', '10+ years', 'How do you decide whether to use micro-frontends?', 'Use independent frontend deployment only when organizational ownership and release independence justify integration, runtime, performance, and shared-experience costs. Start with simpler route or package boundaries and define navigation, design, telemetry, and failure contracts before adopting runtime composition.', 'Separate a frequently released partner portal only if its team and operational needs are genuinely independent.', false),
('Azure', '0-2 years', 'What is the difference between an Azure resource group and a subscription?', 'A subscription is a billing and governance boundary for Azure resources; a resource group is a logical management container for related resources within a subscription. Access, policy, and lifecycle can be applied at different scopes.', 'Place a web application and its related monitoring resources in a resource group while using separate subscriptions for production and development.', false),
('Azure', '0-2 years', 'What is Azure App Service commonly used for?', 'App Service is a managed hosting platform for web applications and APIs. It provides deployment and scaling features while the application team remains responsible for application behavior, configuration, identity, and operational readiness.', 'Deploy an ASP.NET Core API to an App Service and configure its managed identity for Key Vault access.', false),
('Azure', '3-5 years', 'When would you choose Azure Service Bus over a storage queue?', 'Compare ordering, sessions, duplicate detection, dead-lettering, transactions, throughput, and operational needs against the workload. The best choice depends on required delivery semantics and service limits, not on a general claim that one is always better.', 'Choose sessions when related order events require ordered processing and the selected tier supports the needed throughput.', false),
('Azure', '3-5 years', 'How do deployment slots help reduce release risk in Azure App Service?', 'Slots provide separate app environments that can be warmed and validated before a traffic swap. Verify slot-specific settings and external side effects; a swap does not make database changes or background processing automatically safe.', 'Warm a staging slot and run health checks before swapping it into production after a backward-compatible schema change.', false),
('Azure', '6-10 years', 'How do you design an Azure workload to meet a recovery-time objective?', 'Translate the recovery target into failure scenarios, dependency recovery behavior, data replication, and operational steps. Choose backup, zone, or regional strategies based on tested restore and failover times, and regularly exercise recovery with measurable evidence.', 'Run a restore drill for a database backup and record actual time to restore service, not just the configured retention period.', false),
('Azure', '6-10 years', 'How do you control noisy-neighbor and quota risks in a shared Azure platform?', 'Track service quotas, capacity, and per-tenant consumption; apply budgets, limits, and isolation where justified. Load-test expected peaks, request quota increases with evidence, and design graceful behavior for throttling rather than assuming capacity is unlimited.', 'Set bounded concurrency for a shared worker pool and alert on throttling and queue age before capacity is exhausted.', false),
('Azure', '10+ years', 'How would you define a landing-zone strategy for multiple product teams?', 'Establish governed subscription structure, identity, network connectivity, policy, security monitoring, and reusable deployment patterns. Keep guardrails automated and risk-based, assign clear platform ownership, and support team autonomy within auditable boundaries.', 'Offer a subscription vending workflow with baseline policies and network integration rather than manually configuring every application.', false),
('Azure', '10+ years', 'How do you decide whether to use managed services or operate infrastructure yourself?', 'Compare product requirements, control needs, reliability, security responsibilities, total operational cost, and exit constraints. Managed services reduce some undifferentiated work but do not remove responsibility for configuration, data, identity, and incident readiness.', 'Use a managed database when its consistency and extension limits fit, while retaining tested backup and access controls.', false),
('SQL', '0-2 years', 'What is the difference between a primary key and a foreign key?', 'A primary key uniquely identifies a row in its table. A foreign key references a key in another table and enforces a relationship according to configured constraints.', 'Orders can have an OrderId primary key and a CustomerId foreign key referencing Customers.', false),
('SQL', '0-2 years', 'Why is a WHERE clause useful in a query?', 'WHERE filters rows before they are returned, limiting results to the records relevant to the task. Correct predicates improve clarity and can reduce unnecessary data transfer, though performance also depends on the plan and indexes.', 'Filter orders by CustomerId and a date range instead of loading every order and filtering in application memory.', false),
('SQL', '3-5 years', 'What is the difference between an INNER JOIN and a LEFT JOIN?', 'INNER JOIN returns rows that match on both sides. LEFT JOIN preserves every row from the left side and returns nulls for missing right-side matches. Filters on the right-side table can change the intended outer-join behavior.', 'Use a left join to list all customers including those with no orders.', false),
('SQL', '3-5 years', 'What is a transaction and why does it matter?', 'A transaction groups database operations under defined atomicity and isolation behavior so partial work is not treated as complete. Choose an isolation level that matches correctness needs and keep transactions bounded to avoid unnecessary contention.', 'Update an account balance and insert its ledger entry in one transaction so they cannot diverge on a failed operation.', false),
('SQL', '6-10 years', 'How do you read a SQL execution plan when a query is slow?', 'Compare estimated and actual rows, operators, scans, joins, sorts, memory grants, and lookup patterns. Identify where cardinality or data distribution differs from assumptions, and test a change with representative parameters rather than optimizing from a single plan screenshot.', 'A large actual-versus-estimated row difference may point to stale statistics or a predicate the optimizer cannot estimate well.', false),
('SQL', '6-10 years', 'When can an index make a database slower?', 'Indexes consume storage and add write, maintenance, and cache costs. A low-selectivity or redundant index may not help a query, while too many indexes can slow inserts and updates. Evaluate read benefit against write workload and maintenance evidence.', 'Remove an unused overlapping index only after checking query plans and production usage over a representative period.', false),
('SQL', '10+ years', 'How do you choose an isolation strategy for a high-throughput transactional system?', 'Start from anomalies the business cannot tolerate, then compare isolation guarantees, locking or versioning behavior, retry requirements, and throughput. Validate under realistic concurrency and keep application invariants protected even when transactions retry.', 'Use optimistic concurrency for independent inventory updates and a guarded transaction for a scarce final reservation.', false),
('SQL', '10+ years', 'How would you plan a zero-downtime schema migration for a very large table?', 'Use backward-compatible expand-and-contract stages, avoid blocking DDL where possible, and backfill in bounded observable batches. Monitor locks, replication lag, and write load; pause safely and ensure old and new application versions coexist during rollout.', 'Add a nullable column, dual-write, backfill with checkpoints, switch reads after validation, and remove old data only in a later deployment.', false),
('System Design', '0-2 years', 'What questions should you ask before drawing a system design?', 'Clarify users, primary actions, scale, latency and availability expectations, data sensitivity, and important constraints. Separate must-have requirements from optional features before choosing components.', 'For a chat system, ask whether one-to-one messaging, group chat, history search, and delivery receipts are required.', false),
('System Design', '0-2 years', 'What is the purpose of a cache in a system?', 'A cache stores reusable data closer to a caller to reduce repeated work or latency. It introduces freshness, invalidation, memory, and failure concerns, so define what can be stale and how misses are handled.', 'Cache public product descriptions briefly while reading current inventory from its authoritative source.', false),
('System Design', '3-5 years', 'How do you estimate whether a database can handle a stated workload?', 'Translate user and request rates into read/write volume, data growth, peak concurrency, and access patterns. Validate with realistic load tests and database limits rather than relying on a single generic throughput number.', 'Estimate peak order writes and catalog reads separately, then test the expected query and index mix.', false),
('System Design', '3-5 years', 'When would you use a message queue in a system design?', 'Use a queue to decouple work, absorb bursts, and retry processing independently when the user does not need a synchronous result. Define durability, ordering, idempotency, dead-letter handling, and visibility into queue age.', 'Accept an order synchronously, then publish fulfillment work for an independent worker.', false),
('System Design', '6-10 years', 'How do you choose between synchronous calls and asynchronous events between services?', 'Use synchronous calls when the caller needs an immediate result and coupling is acceptable. Events suit independent reactions and burst buffering but introduce eventual consistency, replay, and schema evolution. Make the user journey and failure behavior explicit.', 'Checkout may synchronously authorize payment but emit an event after order confirmation for analytics and notifications.', false),
('System Design', '6-10 years', 'How do you design a rate limiter for a distributed API?', 'Define the identity, quota window, burst behavior, and fairness requirements. Use an atomic distributed counter or token-bucket approach with bounded state, account for clock and network failures, and specify whether the system fails open or closed.', 'Apply a per-account token bucket at the gateway and return a retry hint when the permitted burst is exhausted.', false),
('System Design', '10+ years', 'How do you make an architecture decision when key scale assumptions are uncertain?', 'Identify which unknowns materially change the design, gather evidence through prototypes or workload measurements, and preserve reversible choices where uncertainty is high. Document assumptions, decision triggers, and operational costs instead of prematurely optimizing for speculative scale.', 'Start with a modular deployment and define traffic or ownership thresholds that would justify extracting a service.', false),
('System Design', '10+ years', 'How do you define and use service-level objectives in architecture decisions?', 'Choose user-centered indicators, a measurement window, and an error budget that reflects product needs. Use the objectives to guide reliability investment and rollout decisions, while checking that indicators capture critical operations and dependency effects.', 'Set a latency and availability objective for order placement, then slow risky releases when the error budget is being consumed.', false),
('JavaScript / TypeScript', '0-2 years', 'What is the difference between let and const in JavaScript?', 'Both are block-scoped. let allows reassignment; const prevents reassignment of the binding but does not make an object deeply immutable. Prefer const when the variable binding does not need to change.', 'A const array can still have an item pushed into it, but the variable cannot be assigned a different array.', false),
('JavaScript / TypeScript', '0-2 years', 'What does a Promise represent?', 'A Promise represents the eventual fulfillment or rejection of one asynchronous operation. It can be composed with then, catch, and finally or consumed with await inside an async function.', 'Await a fetch call and handle a rejected request with try/catch.', false),
('JavaScript / TypeScript', '3-5 years', 'What is a closure and when is it useful?', 'A closure is a function together with access to variables from its lexical scope. It enables encapsulated state and callbacks, but retained references can also keep data alive longer than intended.', 'A function can capture a retry counter while exposing only a method that increments it.', false),
('JavaScript / TypeScript', '3-5 years', 'How do you safely handle an unknown JSON response in TypeScript?', 'Treat parsed network data as untrusted, validate its shape at runtime, and narrow from unknown to a domain type before use. A TypeScript type annotation alone does not validate data received over HTTP.', 'Check that an object has a string id and a supported status before adding it to typed application state.', false),
('JavaScript / TypeScript', '6-10 years', 'How do you prevent an asynchronous UI response from overwriting newer state?', 'Tie each response to the request or state version that initiated it, and cancel obsolete work when possible. Apply a result only when it is still current, while keeping loading and error states explicit.', 'Use switchMap for a changing search query so a slower earlier request does not replace newer results.', false),
('JavaScript / TypeScript', '6-10 years', 'How do you diagnose a memory leak in a browser application?', 'Use heap snapshots and allocation timelines around a repeatable user journey. Inspect detached DOM nodes, retained event listeners, timers, subscriptions, and caches, then verify the retained objects disappear after cleanup.', 'Navigate repeatedly into and out of a screen and compare heap snapshots for retained component listeners.', false),
('JavaScript / TypeScript', '10+ years', 'How do you evolve a TypeScript monorepo without creating excessive coupling?', 'Define stable package APIs, explicit ownership, and dependency direction; enforce boundaries with tooling and versioning where needed. Share contracts when they represent real ownership, not merely to avoid all duplication, and measure build and release impact.', 'Keep domain packages independently testable and prevent UI packages from importing server implementation internals.', false),
('JavaScript / TypeScript', '10+ years', 'How would you set frontend reliability objectives across a large product?', 'Measure critical user journeys using real-user and synthetic signals, segment by device and network, and define actionable budgets for loading and interaction. Assign ownership for regressions and connect performance changes to release and product decisions.', 'Track checkout interaction latency and completion errors by release rather than relying only on a global bundle-size target.', false),
('EF Core', '0-2 years', 'What is the purpose of a database relationship in an EF Core model?', 'A relationship describes how entities reference one another and maps to database keys and constraints. Configure required or optional relationships to reflect actual domain rules, and understand whether loading related data is explicit or configured.', 'An Order has a required CustomerId foreign key while a customer may have many orders.', false),
('EF Core', '3-5 years', 'What is the N+1 query problem in EF Core?', 'N+1 occurs when one query loads a collection and additional queries execute for each item to retrieve related data. Detect it through SQL logs or traces and address it with projection, intentional related loading, or batching appropriate to the result size.', 'Project customer name with each order in one bounded query instead of querying each customer inside a loop.', false),
('EF Core', '6-10 years', 'How do you handle a transaction that includes both a database write and message publication?', 'A database commit and broker publish are not one atomic operation by default. Use a transactional outbox to commit the business change and pending event together, then publish asynchronously with idempotent consumers and observable retries.', 'Save the order and an outbox event in one database transaction, then have a worker publish the event.', false),
('EF Core', '10+ years', 'How do you manage EF Core model complexity across bounded contexts?', 'Keep persistence models aligned with ownership boundaries and avoid a single shared context that couples unrelated domains. Share infrastructure selectively, define explicit cross-context contracts, and keep migrations and deployment ownership clear.', 'Give billing and fulfillment separate DbContexts and migration responsibility even when they share the same database server.', false),
('LINQ', '0-2 years', 'What does the Select operator do in LINQ?', 'Select transforms each element into a new result while preserving one output for each input. It is commonly used to create a projection and can avoid carrying fields that a caller does not need.', 'Select a list of Customer objects into a list of customer names.', false),
('LINQ', '3-5 years', 'When would you use Any instead of Count in a predicate?', 'Use Any when the question is whether at least one matching item exists. It can stop after the first match, while Count may enumerate more data or translate to a more expensive query depending on the provider.', 'Use orders.Any(order => order.IsLate) to test whether a late order exists.', false),
('LINQ', '6-10 years', 'How do grouping and aggregation affect query cost?', 'Grouping can require sorting, hashing, or database aggregation and may produce large intermediate results. Push aggregation to the provider when appropriate, filter early, and inspect the execution plan and result cardinality.', 'Group sales by month in SQL through an EF projection instead of materializing every sale to aggregate in memory.', false),
('LINQ', '10+ years', 'How do you keep LINQ query abstractions composable and predictable?', 'Keep deferred query construction separate from execution, expose supported composition explicitly, and avoid abstractions that hide materialization or provider translation. Document ownership and ensure callers cannot accidentally execute unbounded queries.', 'Use a specification for shared filters and let the application boundary choose the projection, limit, and execution point.', false),
('Behavioral', '0-2 years', 'How can you describe a mistake in a project professionally?', 'Choose a real mistake, explain its impact and your responsibility, describe how you corrected it, and state what changed in your process. Keep the focus on learning and prevention rather than blame or excuses.', 'Explain how a missing edge-case test caused a defect and how you added a checklist and regression test afterward.', false),
('Behavioral', '3-5 years', 'How do you prioritize when two urgent tasks compete?', 'Clarify impact, deadline, dependencies, and risk with the relevant owners. Make trade-offs visible, agree on sequencing, and communicate early if a commitment must change instead of silently sacrificing quality.', 'Compare a customer outage with a requested feature deadline, align on mitigation first, then update the feature plan.', false),
('Behavioral', '6-10 years', 'Tell me about a time you improved a team process.', 'Describe the observed problem, how you involved the team, the change you proposed, and measurable results. Include drawbacks or follow-up adjustments and distinguish your contribution from the team outcome.', 'Explain how smaller pull requests reduced review wait time and how the team measured the effect over several iterations.', false),
('Behavioral', '10+ years', 'How do you handle a high-impact decision that later proves wrong?', 'Own the decision and its impact, communicate facts promptly, contain harm, and invite the right people to reassess assumptions. Correct the system, document learning without blame, and improve decision signals or reversibility for future choices.', 'Explain how an architecture choice increased operational burden, how you led a safe correction, and what decision checkpoint you added.', false),
('ASP.NET Core', '0-2 years', 'What is dependency injection in ASP.NET Core?', 'Dependency injection lets the framework create and provide registered services to application components. It reduces direct construction coupling, but lifetime choices must match the service and its dependencies.', 'Register an application service as scoped and request it through a controller constructor.', false),
('ASP.NET Core', '3-5 years', 'How should configuration differ between development and production?', 'Keep non-secret defaults in configuration files and environment-specific settings in deployment configuration or environment variables. Retrieve secrets through an approved secret store or identity, validate required settings at startup, and never rely on development secrets in production.', 'Bind and validate a typed options class, with the production connection credential supplied through managed identity or a secret provider.', false),
('ASP.NET Core', '6-10 years', 'How do you prevent thread-pool starvation in an ASP.NET Core service?', 'Use asynchronous APIs for I/O, avoid blocking waits and synchronous locks around request work, and bound background concurrency. Diagnose queue length, thread count, CPU, and dependency latency together; increasing minimum threads is not a substitute for removing blocking work.', 'Replace Task.Wait on an outbound HTTP call with awaited I/O and propagate cancellation.', false),
('ASP.NET Core', '10+ years', 'How do you define production readiness for a critical ASP.NET Core API?', 'Set measurable service objectives and verify capacity, identity, data recovery, dependency timeouts, observability, deployment safety, and incident ownership. Exercise failure and recovery paths before launch and close gaps with accountable owners.', 'Run a pre-launch exercise for database failover and confirm alerting, runbooks, and rollback ownership.', false),
('REST APIs', '0-2 years', 'What is the difference between PUT and PATCH?', 'PUT generally replaces a resource representation at a known URI and is intended to be idempotent. PATCH applies a partial modification described by its format; the operation may or may not be idempotent depending on its semantics.', 'PUT can replace a profile representation, while PATCH can update only its display name.', false),
('REST APIs', '3-5 years', 'What is idempotency in an HTTP API?', 'An operation is idempotent when repeating the same request has the same intended effect as performing it once. Safe retry design also depends on response semantics, deduplication, and whether external side effects are repeated.', 'A delete request for the same resource should not create a second destructive effect when retried.', false),
('REST APIs', '6-10 years', 'How do you design an API for optimistic concurrency?', 'Expose a version or validator such as an ETag and require clients to submit the version they observed when updating. Reject stale writes with a clear conflict response and provide a safe way to reload or reconcile.', 'Return an ETag on GET and require If-Match for an update to prevent silently overwriting a newer edit.', false),
('REST APIs', '10+ years', 'How do you manage API lifecycle and deprecation across a large ecosystem?', 'Maintain discoverable ownership and usage telemetry, communicate supported versions and timelines, and provide migration guidance. Automate compatibility checks and coordinate retirement based on consumer evidence and risk, with an exception process for critical clients.', 'Publish a deprecation date and migration guide, then verify remaining client traffic before removing the old contract.', false),
('Testing', '0-2 years', 'Why should a test be deterministic?', 'A deterministic test produces the same result for the same inputs and controlled conditions. Nondeterminism wastes debugging time and reduces trust; control time, randomness, external dependencies, and shared state where relevant.', 'Inject a clock into expiration logic so a test can verify boundary times without waiting for real time.', false),
('Testing', '3-5 years', 'How do you test retry behavior without waiting for real delays?', 'Inject or configure a controllable time provider or delay abstraction and use a fake dependency that fails in a known sequence. Assert attempts, cancellation, and final outcome without real sleeps or external network access.', 'Use a fake clock and a dependency that fails twice then succeeds to verify a bounded retry policy.', false),
('Testing', '6-10 years', 'When is a contract test valuable?', 'A contract test verifies assumptions at a boundary between independently changing components, such as an API consumer and provider. It complements integration tests and should reflect a maintained contract rather than duplicating implementation details.', 'Verify that a provider continues returning required fields and status behavior used by a separately deployed consumer.', false),
('Testing', '10+ years', 'How do you keep test architecture aligned with system architecture?', 'Assign tests to boundaries that can detect the intended failure, keep ownership clear, and remove redundant suites that only add maintenance. Review escaped defects and diagnosis time to adjust coverage, and include operational and recovery scenarios for critical flows.', 'Use component contract tests for service boundaries and a small set of end-to-end checks for critical customer journeys.', false),
('Data Structures & Algorithms', '0-2 years', 'How do you use a stack to solve a problem?', 'A stack is last-in, first-out and is useful when the most recent unresolved item should be processed first. Identify the invariant for what each stored item represents and ensure each input is pushed and popped a bounded number of times when seeking linear time.', 'Use a stack to validate that each closing bracket matches the most recent unmatched opening bracket.', false),
('Data Structures & Algorithms', '3-5 years', 'How do you recognize a sliding-window problem?', 'Look for a contiguous sequence where a moving start and end can maintain a condition incrementally. State how adding and removing elements changes the invariant; if the condition is not monotonic, the simple window may not be correct.', 'Track character counts while expanding a substring window and shrink the left side when a duplicate violates the condition.', false),
('Data Structures & Algorithms', '6-10 years', 'How do you select between a heap and sorting for a top-k problem?', 'A bounded heap can find k items in O(n log k) time and O(k) extra space, while sorting is simpler and costs O(n log n). Consider k relative to n, streaming requirements, ordering of final results, and implementation clarity.', 'Maintain a min-heap of the largest 100 scores while processing a stream too large to retain in memory.', false),
('Data Structures & Algorithms', '10+ years', 'How do you reason about algorithmic worst cases in an adversarial workload?', 'Analyze input distributions and adversarial patterns, choose algorithms with bounded worst-case behavior where required, and set resource limits for parsing and execution. Benchmark skewed cases and account for denial-of-service risk as well as average throughput.', 'Use a hash strategy with understood collision behavior and cap request size for untrusted collections.', false),
('DevOps', '0-2 years', 'What is infrastructure as code?', 'Infrastructure as code describes cloud or platform resources in versioned, reviewable files that can be validated and deployed repeatably. It reduces manual drift but still requires safe state handling, permissions, and change review.', 'Define an app service and its monitoring resource in a template and deploy the reviewed version to a test environment.', false),
('DevOps', '3-5 years', 'How do you manage environment-specific configuration without rebuilding an artifact?', 'Keep the build artifact immutable and inject validated configuration at deployment or runtime through an approved configuration system. Separate secrets from ordinary settings and verify the promoted artifact digest is unchanged across environments.', 'Promote one container image digest while each environment supplies its own non-secret endpoint and identity configuration.', false),
('DevOps', '6-10 years', 'How do you manage a failed production deployment?', 'Use predefined health signals to stop rollout, assess whether rollback or roll-forward is safer, and communicate ownership and impact. Preserve logs and deployment metadata, verify recovery from the user perspective, and follow up with a blameless review and corrective actions.', 'Pause a canary when error rate breaches its guardrail, restore the previous artifact, and verify critical transactions succeed.', false),
('DevOps', '10+ years', 'How would you improve deployment frequency without increasing change-failure risk?', 'Reduce batch size, automate repeatable verification, improve observability and rollback, and use progressive delivery with risk-based controls. Measure lead time and change failure together, and invest in architecture and test reliability where they constrain safe delivery.', 'Deploy small changes behind a feature flag with automated canary analysis and an owned rollback path.', false),
('Identity & Security', '0-2 years', 'Why should an application use HTTPS?', 'HTTPS protects data in transit from passive reading and tampering and helps authenticate the server through certificates. It does not replace authorization, safe secret storage, or protection against vulnerabilities in the application itself.', 'Use HTTPS for login and API traffic, then still validate each caller''s permission on the server.', false),
('Identity & Security', '3-5 years', 'How do you prevent cross-site request forgery?', 'For browser requests authenticated by automatically attached cookies, use framework protections such as anti-forgery tokens and appropriate SameSite settings, validate origins where applicable, and avoid state-changing GET requests. The correct controls depend on the authentication model.', 'Require a valid anti-forgery token for a cookie-authenticated account update POST.', false),
('Identity & Security', '6-10 years', 'How do you approach threat modeling for a new feature?', 'Identify assets, trust boundaries, actors, entry points, and abuse cases, then prioritize mitigations by likelihood and impact. Revisit the model when architecture changes and link mitigations to tests, ownership, and operational detection.', 'For file upload, model malicious content, oversized payloads, unauthorized access, storage exposure, and scanning failure paths.', false),
('Identity & Security', '10+ years', 'How do you prioritize security findings across a large application portfolio?', 'Combine exploitability, exposure, asset criticality, reachable attack paths, and compensating controls instead of sorting only by scanner severity. Assign owners and deadlines, track remediation and exceptions, and improve systemic controls that remove whole classes of findings.', 'Prioritize an exposed exploitable authentication flaw over an unreachable library finding while tracking both to closure.', false),
('Microservices', '0-2 years', 'What is service discovery?', 'Service discovery lets a caller locate an available service instance through platform naming or a registry instead of hard-coding machine addresses. The platform and client still need health, timeout, and retry behavior for instances that become unavailable.', 'Call a stable service DNS name inside a container platform rather than storing a pod IP in application code.', false),
('Microservices', '3-5 years', 'How do you handle a service timeout in a caller?', 'Set a deadline appropriate to the user journey, propagate remaining time where possible, and distinguish timeout from a definitive failure. Retry only safe transient operations with bounded backoff and jitter; use a fallback only when its semantics are valid.', 'Return an explicit pending operation for a long-running workflow instead of retrying a timed-out create request blindly.', false),
('Microservices', '6-10 years', 'How do you make a service resilient to a failing downstream dependency?', 'Combine bounded timeouts with concurrency control and carefully scoped retries or circuit breaking. Protect critical capacity, define meaningful degraded behavior, and monitor dependency latency, failure rate, and queueing so a local failure does not cascade.', 'Serve cached non-sensitive catalog details while rejecting a new reservation if authoritative inventory is unavailable.', false),
('Microservices', '10+ years', 'How do you choose ownership boundaries for a service portfolio?', 'Use domain capabilities, data ownership, team responsibility, change coupling, and operational load as evidence. Boundaries should let teams deliver independently without excessive cross-service coordination; revisit them as product and organizational structure change.', 'Split a service only when its capability and team can own its API, data, reliability, and lifecycle independently.', false)
