-- Run in Supabase after schema.sql. Adds band-specific interview Q&A; the first ten questions per technology are free.
create table if not exists public.experience_questions (
  id uuid primary key default gen_random_uuid(),
  topic text not null,
  experience_band text not null check (experience_band in ('0-2 years', '3-5 years', '6-10 years', '10+ years')),
  question text not null,
  answer text not null,
  example text not null,
  company_tags text[] not null default '{}',
  is_free boolean not null default false,
  unique (topic, experience_band, question)
);

alter table public.experience_questions
  add column if not exists company_tags text[] not null default '{}';

alter table public.experience_questions enable row level security;
revoke all on public.experience_questions from anon, authenticated;
grant all on public.experience_questions to service_role;

on conflict (topic, experience_band, question) do update
set     answer = excluded.answer,
    example = excluded.example,
    is_free = excluded.is_free;


('LINQ', '0-2 years', 'What is LINQ used for in C#?', 'LINQ provides a consistent way to filter, project, group, and order data in collections and query providers. Some operators run in memory while IQueryable providers translate supported expressions into another query language, so understand where execution happens.', 'Use Where and Select to create a list of active customer names from a collection.', false),
('LINQ', '0-2 years', 'What is the difference between IEnumerable and IQueryable?', 'IEnumerable represents values iterated in .NET; its operators generally run in process. IQueryable carries an expression tree that a provider may translate, for example to SQL. Materializing an IQueryable too early can pull many rows into memory.', 'Apply Where to an EF Core IQueryable before ToListAsync so the filter can run in the database.', false),
('LINQ', '3-5 years', 'What is deferred execution and when can it cause a bug?', 'Many LINQ operators build a query that executes only when enumerated. Re-enumerating can repeat database work or observe changed source data. Materialize once when a stable snapshot is required, while avoiding unnecessary materialization of large sequences.', 'Calling Count and then iterating an EF query can execute it twice; project and materialize once if both operations need the same results.', false),
('LINQ', '3-5 years', 'When should you use SelectMany instead of Select?', 'Select projects each element to one result; SelectMany projects each element to a sequence and flattens those sequences into one stream. It is useful for one-to-many relationships but can expand result size quickly.', 'SelectMany each Order.Lines to produce one sequence of all line items before grouping by product.', false),
('LINQ', '6-10 years', 'How do you avoid an N+1 query pattern when using LINQ with an ORM?', 'Keep the query provider in control until filtering and projection are translated, inspect executed SQL, and load related data intentionally. Use a projection or a deliberate split query where appropriate; avoid assuming that navigation-property access is free.', 'Project order number and customer name in one query instead of loading each order and then separately fetching its customer.', false),
('LINQ', '6-10 years', 'How would you optimize a large in-memory LINQ pipeline?', 'Measure allocations and elapsed time, reduce repeated enumeration and intermediate collections, and choose data structures that fit lookup patterns. Preserve clarity and correctness; only replace LINQ with loops or specialized algorithms when profiling identifies a meaningful hot path.', 'Build a HashSet of permitted IDs once instead of repeatedly scanning a list inside a large filter.', false),
('LINQ', '10+ years', 'What constraints apply when an IQueryable provider translates a LINQ expression?', 'A provider translates an expression tree to its target language and supports only a subset of .NET operations. A valid in-memory expression may fail translation or produce different null and collation semantics in SQL. Keep provider-specific queries explicit and validate generated behavior against the real provider.', 'Use a database-translatable predicate for an EF query, then perform a custom formatting step after selecting the small result set.', false),
('LINQ', '10+ years', 'How do you design reusable query composition without hiding database costs?', 'Expose composable query specifications or focused repository methods with clear ownership, and keep the execution boundary visible. Avoid abstractions that trigger hidden materialization, unbounded includes, or provider-specific behavior that callers cannot inspect.', 'Return an IQueryable only within a persistence boundary and have the application service choose a bounded projection and execute it once.', false),

('Behavioral', '0-2 years', 'How should you answer a question about a project you worked on?', 'Explain the project goal, your specific contribution, a challenge, the actions you took, and the result. Be clear about what you personally did versus what the team delivered, and do not claim work you did not perform.', 'Describe the feature you implemented, how you tested it, and one improvement you would make after feedback.', false),
('Behavioral', '0-2 years', 'How do you respond when you do not know an interview answer?', 'Say what you know, state the part you are unsure about, and reason from first principles or ask a clarifying question. Avoid bluffing; explain how you would verify the answer in real work.', 'For an unfamiliar cloud service, clarify the requirement and compare it with a service category you understand before naming assumptions.', false),
('Behavioral', '3-5 years', 'Tell me about a time you received difficult feedback.', 'Use a concrete example: describe the context, the feedback, how you checked your understanding, what you changed, and the outcome. Show learning without blaming others or presenting a fabricated success.', 'Explain how code-review feedback led you to add a missing failure-path test and apply that lesson to later changes.', false),
('Behavioral', '3-5 years', 'How do you handle disagreement about a technical design?', 'Clarify the shared goal and constraints, compare options with evidence, and make risks and reversibility explicit. Seek input from affected owners and commit to the agreed decision while recording unresolved concerns.', 'Compare a queue and synchronous call using latency, retry, and consistency needs, then propose a small test if evidence is missing.', false),
('Behavioral', '6-10 years', 'How do you describe a production incident you helped resolve?', 'Explain customer impact, your role, the immediate mitigation, investigation evidence, and the durable corrective actions. Separate facts from hypotheses and avoid implying individual heroics instead of team response and prevention.', 'Describe how you used correlated traces to identify a dependency timeout, restored service with a safe mitigation, and added an alert and regression test.', false),
('Behavioral', '6-10 years', 'How do you prioritize technical debt against feature delivery?', 'Connect debt to measurable delivery, reliability, security, or operating costs. Present options and risk, negotiate incremental work with stakeholders, and verify whether the investment changed the expected outcome.', 'Split a risky database migration into a compatibility step that also enables a committed product feature.', false),
('Behavioral', '10+ years', 'How do you influence an architecture decision across teams without direct authority?', 'Build a shared understanding of user and operational outcomes, involve teams that own affected systems, and present evidence-based options with migration costs. Provide a paved path, clarify decision ownership, and use feedback and adoption data to refine the direction.', 'Publish a short decision record and a reference implementation, then incorporate rollout feedback from service owners.', false),
('Behavioral', '10+ years', 'How do you develop engineers while maintaining delivery accountability?', 'Set clear outcomes and ownership, delegate meaningful decisions with guardrails, and tailor coaching to each engineer. Review progress through observable results and regular feedback, addressing delivery risks early without taking over all implementation.', 'Pair on an initial design review, let the engineer own rollout and monitoring, then discuss results in a retrospective.', false),

('ASP.NET Core', '0-2 years', 'What happens to an HTTP request in an ASP.NET Core application?', 'The hosting server accepts the connection and passes the request through the configured middleware pipeline. Middleware can inspect, modify, short-circuit, or pass control onward; endpoint routing selects a handler, and the response travels back through the pipeline.', 'A request can pass through exception handling, routing, authentication, authorization, and finally a controller endpoint.', false),
('ASP.NET Core', '0-2 years', 'What is middleware in ASP.NET Core?', 'Middleware is a component in the HTTP request pipeline. It can run logic before and after the next component, or end the pipeline early. Order matters because later middleware sees the request state produced by earlier middleware.', 'Place exception handling near the start of the pipeline so it can observe errors from later components.', false),
('ASP.NET Core', '3-5 years', 'How should authentication and authorization be configured in an ASP.NET Core API?', 'Authentication establishes the caller identity; authorization checks whether that identity may perform an action. Configure the authentication scheme, place authentication before authorization in the pipeline, and express access with policies or resource checks.', 'Require an Orders.Read policy on a read endpoint and separately verify ownership for a particular customer record.', false),
('ASP.NET Core', '3-5 years', 'How do you validate API requests and return useful validation errors?', 'Validate untrusted input at the application boundary and return a consistent problem response with field-level details that do not expose internals. Keep business invariants in the appropriate application or domain layer rather than relying only on transport validation.', 'Reject a missing address with a validation problem response before attempting to save an order.', false),
('ASP.NET Core', '6-10 years', 'How do you investigate memory growth in a long-running ASP.NET Core process?', 'Correlate managed heap, allocation rate, GC pause, working set, and request patterns over time. Capture a representative dump or trace under approved conditions, inspect retained object graphs and event subscriptions, and distinguish managed retention from native or container memory.', 'Compare heap snapshots after repeated report requests to find a cache that grows without eviction.', false),
('ASP.NET Core', '6-10 years', 'How do you make background work reliable in an ASP.NET Core application?', 'Use a hosted worker for bounded in-process work that may be retried after restart only if loss is acceptable. For durable or independently scaled jobs, persist work to a queue or database, make processing idempotent, and define retry, poison-message, and shutdown behavior.', 'A BackgroundService can drain a durable queue and acknowledge a message only after its database update commits.', false),
('ASP.NET Core', '10+ years', 'How would you structure a large ASP.NET Core codebase for multiple teams?', 'Organize around business capabilities with explicit dependency direction and ownership. Keep transport, application, and persistence responsibilities clear without introducing layers that provide no boundary. Enforce architecture through tests and delivery conventions, and extract services only when ownership or scaling justifies the cost.', 'Keep checkout and inventory modules in one deployable application while enforcing separate data access and contracts.', false),
('ASP.NET Core', '10+ years', 'How do you roll out a breaking API change safely?', 'Use telemetry to identify consumers, introduce a compatible contract or version, support a migration window, and coordinate validation with clients. Communicate deprecation, monitor adoption, and remove old behavior only after agreed usage and risk criteria are met.', 'Add a versioned endpoint while clients migrate, then retire the prior endpoint after usage falls below the published threshold.', false),

('REST APIs', '0-2 years', 'What makes an API RESTful in practical terms?', 'A REST-style API exposes resources through consistent identifiers and HTTP semantics, uses representations such as JSON, and remains stateless between requests. Teams should prioritize predictable contracts, correct methods and status codes, and clear documentation over labels.', 'Use GET /orders/123 to retrieve a representation and POST /orders to create a new order.', false),
('REST APIs', '0-2 years', 'When should an API return 400, 401, 403, or 404?', 'Use 400 for a malformed or invalid request, 401 when authentication is missing or invalid, 403 when an authenticated caller lacks permission, and 404 when the resource is absent or intentionally concealed. Apply a consistent documented policy.', 'A valid signed-in caller without the required role receives 403 for a protected administrative operation.', false),
('REST APIs', '3-5 years', 'How do you make a create endpoint safe when clients retry after a timeout?', 'Use an idempotency key scoped to the caller and operation, persist the key and outcome atomically with the business change, and return the recorded result for a duplicate request. Define expiry and payload-mismatch behavior.', 'A unique constraint on account ID and idempotency key prevents a network retry from creating a second payment.', false),
('REST APIs', '3-5 years', 'How should pagination be designed for a growing API collection?', 'Use bounded page sizes and a stable ordering. Offset pagination is simple but can become expensive and shift under concurrent writes; cursor pagination is often more stable for large or changing datasets. Document continuation and filtering semantics.', 'Return a next cursor based on created time plus a unique ID so records with equal timestamps are ordered consistently.', false),
('REST APIs', '6-10 years', 'How do you evolve a public API without breaking existing consumers?', 'Treat the schema and behavior as a versioned contract. Prefer additive changes, test old and new consumer assumptions, measure field and endpoint usage, and provide deprecation timelines. Version when semantics cannot remain compatible and define an explicit migration path.', 'Add an optional response field, publish client guidance, and observe adoption before considering removal of a legacy field.', false),
('REST APIs', '6-10 years', 'How do you design consistent errors across a set of APIs?', 'Use a standard error representation with stable machine-readable codes, safe user-facing detail, and a correlation identifier. Map known domain and validation failures deliberately while logging unexpected errors with access controls and enough context for investigation.', 'Return a Problem Details response with a validation code and trace ID, not a stack trace.', false),
('REST APIs', '10+ years', 'How would you govern API contracts across independent teams?', 'Define lightweight standards for identity, errors, compatibility, observability, and lifecycle, then automate contract linting and consumer checks. Keep ownership and escalation clear, allow justified exceptions, and measure reliability and adoption rather than centralizing every design decision.', 'A shared API review checks breaking-change risk and security while each team owns its domain endpoints.', false),
('REST APIs', '10+ years', 'When should a synchronous API operation become asynchronous?', 'Move work to an asynchronous workflow when duration, burst absorption, independent retries, or downstream availability makes a single request-response contract unreliable. Return a durable operation reference, define status and cancellation semantics, and provide observability and idempotency.', 'Return 202 with an operation URL after persisting a report-generation job to a durable queue.', false),

('Testing', '0-2 years', 'What is the difference between a unit test and an integration test?', 'A unit test checks a small unit of behavior with controlled dependencies. An integration test verifies that multiple real components work together, such as an API and database. Both should have clear purpose and deterministic assertions.', 'Unit-test a price calculator directly, then integration-test the repository against a disposable test database.', false),
('Testing', '0-2 years', 'What makes a useful automated test assertion?', 'A useful assertion checks an observable behavior that matters to a caller, uses clear setup and failure output, and avoids depending on unrelated implementation details. Include representative boundary and failure cases.', 'Assert that an invalid order returns a validation error and does not create a database record.', false),
('Testing', '3-5 years', 'When should you mock a dependency in a unit test?', 'Mock an external boundary when the test needs deterministic control over a collaboration or failure. Prefer real simple value objects and focused fakes where they are clearer. Too many mocks can test an imagined interaction rather than meaningful behavior.', 'Use a fake payment gateway to simulate a timeout and verify the service does not mark the order paid.', false),
('Testing', '3-5 years', 'How do you test an API endpoint that depends on a database?', 'Combine focused application tests with integration tests that run the endpoint and persistence against a realistic disposable database. Seed known data, isolate state, assert both response and persisted effects, and clean up reliably.', 'Send a create-order HTTP request to a test host and verify the saved order through a fresh database scope.', false),
('Testing', '6-10 years', 'How do you reduce flaky tests in CI?', 'Find whether flakiness comes from shared state, timing assumptions, external services, nondeterministic data, or resource contention. Make dependencies explicit, use controlled clocks and bounded polling where appropriate, and fix the source instead of rerunning until green.', 'Replace a fixed sleep with waiting for a specific observable condition under a bounded timeout.', false),
('Testing', '6-10 years', 'How do you decide what belongs in an end-to-end test suite?', 'Reserve end-to-end tests for high-value user journeys and cross-boundary contracts that lower-level tests cannot prove. Keep them deterministic, limit unnecessary setup, and cover detailed branch logic with faster tests to control cost and diagnosis time.', 'Keep one checkout journey end-to-end while testing tax and discount edge cases at the service layer.', false),
('Testing', '10+ years', 'How do you measure whether a test strategy gives adequate risk coverage?', 'Map important failure modes and user journeys to layers of verification, then evaluate escaped defects, change lead time, test reliability, and diagnosis cost. Coverage percentages can identify unexecuted code but do not establish correctness by themselves.', 'Track whether payment failure, duplicate request, and recovery scenarios are verified at the boundary that can detect each failure.', false),
('Testing', '10+ years', 'How would you improve confidence in a large system without making CI prohibitively slow?', 'Use a test pyramid with fast deterministic checks on every change, parallelize isolated suites, and run expensive broad scenarios at deliberate gates. Use risk-based selection only with fallback full validation, monitor flake rates, and preserve reproducible artifacts for failures.', 'Run unit and contract checks for every commit, focused integration suites for changed components, and a scheduled broader resilience suite.', false),

('Data Structures & Algorithms', '0-2 years', 'How do you choose between an array and a linked list?', 'An array offers constant-time indexed access and good memory locality, while insertion in the middle may require shifting elements. A linked list supports local insertion when a node is already known but has traversal and allocation costs. Choose based on actual operations.', 'Use a list or array for indexed UI results; do not select a linked list only because insertion is theoretically constant time.', false),
('Data Structures & Algorithms', '0-2 years', 'How do you explain Big O time complexity?', 'Big O describes how resource use grows with input size while focusing on the dominant growth term. It helps compare algorithms at scale, but constants, memory, and realistic input sizes still matter.', 'A nested scan over n items is O(n squared), while sorting then scanning is typically O(n log n).', false),
('Data Structures & Algorithms', '3-5 years', 'When can a hash map improve an algorithm?', 'A hash map can replace repeated linear searches with expected constant-time lookups, trading additional memory for speed. Account for key equality, collision behavior, and whether ordering is required.', 'Store each value''s index in a dictionary to find a complement in a typical two-sum problem in linear expected time.', false),
('Data Structures & Algorithms', '3-5 years', 'How do you identify whether a two-pointer approach fits a problem?', 'Look for a sequence or pair relationship where moving one pointer can safely eliminate candidates, often because the data is sorted or has a monotonic property. State the invariant that proves no skipped candidate can be the answer.', 'For a sorted array and target sum, move the left or right pointer based on whether the current sum is too small or too large.', false),
('Data Structures & Algorithms', '6-10 years', 'How do you choose between breadth-first and depth-first search?', 'BFS explores by distance and finds shortest paths in an unweighted graph, using a queue and potentially more frontier memory. DFS explores deeply and suits reachability, cycle detection, and backtracking. Consider graph size, depth, and required output.', 'Use BFS for minimum number of hops in an unweighted network and DFS for checking whether a node is reachable.', false),
('Data Structures & Algorithms', '6-10 years', 'How do you reason about memory limits in a dynamic programming solution?', 'Define the state and transition, estimate state count and per-state storage, then identify whether old states can be discarded. Rolling arrays or a one-dimensional recurrence can reduce memory if dependency order preserves correctness.', 'For a recurrence using only the previous two values, keep two rolling states instead of a full table.', false),
('Data Structures & Algorithms', '10+ years', 'How do you evaluate an algorithmic optimization beyond asymptotic complexity?', 'Measure representative workloads and account for constants, allocation, cache locality, concurrency, worst-case behavior, and operational limits. Confirm that the optimization preserves correctness and remains maintainable for the team.', 'Benchmark a bounded top-k heap against full sorting using realistic input sizes and allocation profiles.', false),
('Data Structures & Algorithms', '10+ years', 'How would you choose an algorithm for a stream too large to fit in memory?', 'Clarify accuracy, ordering, update, and latency requirements. Use external-memory algorithms, partitioning, or sketches when their guarantees fit; define error bounds and recovery behavior, and validate resource use with realistic skew.', 'Use a mergeable approximate cardinality sketch for a large analytics stream when bounded estimation error is acceptable.', false),

('DevOps', '0-2 years', 'What is the purpose of a CI pipeline?', 'Continuous integration automatically builds and verifies proposed changes so defects are detected near the change. A useful pipeline runs reproducible checks, reports failures clearly, and produces artifacts that can be promoted consistently.', 'On each pull request, restore dependencies, compile the service, and run its focused test suite.', false),
('DevOps', '0-2 years', 'What is the difference between a container image and a running container?', 'An image is a packaged, mostly immutable filesystem and metadata used to start a workload. A container is a running instance with its own process and runtime configuration. Persist important data outside the container filesystem.', 'Build an API image once and start it with environment-specific ports and configuration.', false),
('DevOps', '3-5 years', 'How do you promote a build from test to production safely?', 'Build an immutable artifact once, verify it in progressively representative environments, and promote the same artifact with controlled configuration. Use approvals or automated gates appropriate to risk, monitor health, and maintain a rollback or roll-forward plan.', 'Deploy the same image digest to staging and production rather than rebuilding from a different source snapshot.', false),
('DevOps', '3-5 years', 'How should application secrets be handled in a deployment pipeline?', 'Keep secrets in an approved secret store, grant short-lived least-privilege access to the workload or pipeline, and prevent values from appearing in logs or artifacts. Rotate exposed credentials and audit access.', 'Use a deployment identity to retrieve a runtime secret from Key Vault instead of writing it into a checked-in configuration file.', false),
('DevOps', '6-10 years', 'How do you design a deployment rollback strategy?', 'Define rollback triggers and understand whether the change is reversible across application, data, and infrastructure. Prefer backward-compatible schema transitions and immutable artifacts; test rollback or roll-forward procedures and verify user impact after action.', 'Keep the old application version compatible with the expanded database schema until the new version is stable.', false),
('DevOps', '6-10 years', 'What signals should determine whether a new release is healthy?', 'Use user-centered service level indicators such as success rate, latency, and saturation, segmented by critical operation and release. Combine metrics with logs and traces, set a comparison window, and roll back or pause rollout when agreed thresholds are breached.', 'Compare checkout error and p95 latency for canary traffic with the stable version before expanding the rollout.', false),
('DevOps', '10+ years', 'How do you balance delivery speed with governance across many teams?', 'Automate essential security, reliability, and compliance checks into reusable paved roads. Make policy ownership and exception processes explicit, measure lead time and failure outcomes, and avoid gates that provide no actionable risk reduction.', 'Provide approved infrastructure modules with policy checks and a documented path for a justified exception.', false),
('DevOps', '10+ years', 'How would you improve software supply-chain security?', 'Establish provenance for source and artifacts, pin and scan dependencies, protect build identities, produce attestations or an SBOM where required, and control artifact promotion. Prioritize remediation based on exploitability and production exposure, not raw scanner counts alone.', 'Sign the build artifact in a protected pipeline and verify its provenance before production deployment.', false),

('Identity & Security', '0-2 years', 'What is the difference between authentication and authorization?', 'Authentication verifies who a caller is; authorization decides what that authenticated caller may do. They are separate checks, and an authenticated user should not automatically receive access to every resource.', 'A valid login authenticates a user, while a policy checks whether they can administer a particular account.', false),
('Identity & Security', '0-2 years', 'Why should passwords not be stored as plain text?', 'Plain-text passwords expose every account if the database is read. Store passwords using a dedicated, slow salted password-hashing algorithm with appropriate parameters; never use reversible encryption or a fast general-purpose hash as a substitute.', 'Use a maintained authentication provider or a framework password hasher rather than writing custom password storage code.', false),
('Identity & Security', '3-5 years', 'How do you protect an API from broken object-level authorization?', 'Authorize every operation against both the caller and the specific resource. Do not rely on an unguessable ID or a UI check. Centralize policy where practical and test cross-user access attempts for read, update, and delete paths.', 'Before returning an order, verify its account belongs to the authenticated customer, even when the order ID is valid.', false),
('Identity & Security', '3-5 years', 'How should an application manage access tokens?', 'Use a trusted identity provider and validate issuer, audience, signature, expiry, and required claims. Keep tokens out of logs and insecure storage, use short lifetimes appropriate to the flow, and design refresh and revocation behavior deliberately.', 'An API validates a bearer token audience for its own resource instead of accepting any token from the identity provider.', false),
('Identity & Security', '6-10 years', 'How do you reduce the risk of a compromised service credential?', 'Prefer workload identity and short-lived credentials, constrain permissions and resource scope, separate identities by workload and environment, and monitor anomalous use. Have a tested rotation and revocation procedure and avoid shared human credentials.', 'Give one worker identity read access to a single queue instead of granting subscription-wide administrator access.', false),
('Identity & Security', '6-10 years', 'How do you design authorization for multi-tenant data?', 'Derive tenant context from a validated identity or trusted server-side mapping, enforce it at every data access boundary, and prevent clients from selecting arbitrary tenant IDs without authorization. Add isolation tests and audit sensitive cross-tenant operations.', 'Include the authorized tenant key in repository queries and test attempts to substitute another tenant identifier.', false),
('Identity & Security', '10+ years', 'How would you establish a practical security program for a growing engineering platform?', 'Prioritize threat modeling for critical flows, secure defaults, identity and secret lifecycle, dependency and artifact hygiene, and observable incident response. Assign accountable owners, automate repeatable checks, and track remediation against risk and delivery impact.', 'Start with internet-facing authentication and payment flows, create owned threat models, then roll reusable controls into service templates.', false),
('Identity & Security', '10+ years', 'How do you handle a suspected credential compromise in production?', 'Contain exposure by revoking or rotating affected credentials, limit access and preserve relevant audit evidence, assess the scope and timeline, and follow incident communication procedures. Validate recovery, search for persistence or misuse, and address the control failure that enabled exposure.', 'Disable the affected workload identity credential, review access logs, rotate dependent secrets, and document verification before restoring normal access.', false),

('Microservices', '0-2 years', 'What is a microservice?', 'A microservice is a small independently owned service boundary with a clear responsibility and contract. It is not merely a small code class; it adds deployment, network, data consistency, and operational responsibilities that must be justified.', 'An independently deployed notification service owns message delivery rather than sharing another service''s private database tables.', false),
('Microservices', '0-2 years', 'Why should each service own its data?', 'Data ownership prevents other services from depending on private schema details and allows a team to evolve its model. Other services should use an explicit API or events, accepting that distributed communication introduces latency and partial failures.', 'An order service requests inventory availability through a contract instead of directly updating inventory tables.', false),
('Microservices', '3-5 years', 'How do you handle a workflow that updates data in two services?', 'Use an explicit distributed workflow such as a saga when one local database transaction cannot cover the operation. Define state transitions, idempotent commands, timeouts, retries, and compensating actions; do not assume compensation perfectly erases external effects.', 'A booking workflow reserves inventory and payment separately, then releases the reservation if payment fails.', false),
('Microservices', '3-5 years', 'How do you make event consumers safe to retry?', 'Assume at-least-once delivery can produce duplicates. Give events stable IDs, make handlers idempotent, persist deduplication or business state atomically with the effect, and monitor retry and dead-letter behavior.', 'Record the event ID in the same transaction that updates the order so redelivery does not apply the transition twice.', false),
('Microservices', '6-10 years', 'How do you evolve an event schema while multiple consumers deploy independently?', 'Prefer additive compatible changes, make consumers tolerant only where safe, version breaking semantics explicitly, and test representative old and new producer-consumer combinations. Track consumer adoption before retiring old fields or event versions.', 'Add an optional currency field while preserving existing amount semantics, then migrate consumers before making it mandatory.', false),
('Microservices', '6-10 years', 'How do you diagnose a latency increase across a service chain?', 'Use distributed traces and consistent correlation to identify the slow span, then correlate it with service saturation, queue age, retries, and dependency health. Check whether fan-out or timeout amplification is involved and mitigate at the narrowest safe boundary.', 'A trace may reveal a retrying inventory call dominates checkout latency while application CPU remains low.', false),
('Microservices', '10+ years', 'When should a team split a monolith into services?', 'Split when independent ownership, deployment, scaling, isolation, or domain boundaries create measurable value that exceeds network, observability, data-consistency, and on-call costs. Start by enforcing a modular boundary and define a reversible extraction path.', 'Extract a high-volume search capability only after its ownership and scaling needs differ materially from the transactional core.', false),
('Microservices', '10+ years', 'How do you prevent a microservice platform from becoming a distributed monolith?', 'Keep service ownership and data boundaries real, minimize synchronous dependency chains, and make contracts and reliability expectations explicit. Review coupling through change patterns and incidents, and consolidate services when independent deployment or ownership is not providing value.', 'If every checkout change requires coordinated releases across six services, revisit the boundaries and the synchronous call graph.', false)
on conflict (topic, experience_band, question) do update
set answer = excluded.answer,
    example = excluded.example,
    is_free = excluded.is_free;

on conflict (topic, experience_band, question) do update
set answer = excluded.answer,
    example = excluded.example,
    is_free = excluded.is_free;

update public.experience_questions
set company_tags = case experience_band
  when '0-2 years' then array['TCS', 'Infosys', 'Accenture']::text[]
  when '3-5 years' then array['TCS', 'Infosys', 'Accenture', 'Microsoft']::text[]
  else array['Microsoft', 'Amazon', 'Google']::text[]
end;

with level_positions as (
    select id, topic, experience_band,
      row_number() over (
        partition by topic, experience_band
        order by question asc, id asc
      ) as level_position
    from public.experience_questions
), ranked_questions as (
    select id, row_number() over (
      partition by topic
      order by level_position asc,
        case experience_band
          when '0-2 years' then 1
          when '3-5 years' then 2
          when '6-10 years' then 3
          when '10+ years' then 4
        end
    ) as topic_position
    from level_positions
)
update public.experience_questions as question
set is_free = ranked_questions.topic_position <= 10
from ranked_questions
where question.id = ranked_questions.id;
